      "kind": "instance",
      "type": "∀ (σ : Type v) {D : Type u} [inst : CommRing D] [UniqueFactorizationMonoid D],\n  UniqueFactorizationMonoid (MvPolynomial σ D)"
    },
    {
      "name": "MvPolynomial.irreducible_sumSMulX",
      "module_name": "Mathlib.RingTheory.MvPolynomial.IrreducibleQuadratic",
      "kind": "theorem",
      "type": "∀ {n : Type u_1} {R : Type u_2} [inst : CommRing R] (c : n →₀ R) [IsDomain R],\n  c.support.Nonempty → (∀ (r : R), (∀ (i : n), r ∣ c i) → IsUnit r) → Irreducible (MvPolynomial.sumSMulX c)"
    },
    {
      "name": "MvPolynomial.irreducible_of_forall_totalDegree_le",
      "module_name": "Mathlib.FieldTheory.SeparablyGenerated",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} {K : Type u_2} {ι : Type u_3} [inst : Field k] [inst_1 : Field K] [inst_2 : Algebra k K] {a : ι → K}\n  {F : MvPolynomial ι k},\n  (∀ (F' : MvPolynomial ι k), F' ≠ 0 → (MvPolynomial.aeval a) F' = 0 → F.totalDegree ≤ F'.totalDegree) →\n    F ≠ 0 → (MvPolynomial.aeval a) F = 0 → Irreducible F"
    },
    {
      "name": "MvPolynomial.irreducible_of_disjoint_support",
      "module_name": "Mathlib.RingTheory.MvPolynomial.IrreducibleQuadratic",
      "kind": "theorem",
      "type": "∀ {n : Type u_1} {R : Type u_2} [inst : CommRing R] [IsDomain R] {f : MvPolynomial n R},\n  f.support.Nontrivial →\n    ∀ {d : n →₀ ℕ},\n      d ∈ f.support →\n        ∀ {i : n},\n          d i = 1 →\n            (↑f.support).PairwiseDisjoint Finsupp.support →\n              (∀ (r : R), (∀ (d : n →₀ ℕ), r ∣ MvPolynomial.coeff d f) → IsUnit r) → Irreducible f"
    },
    {
      "name": "div_eq_quo_add_sum_rem_div",
      "module_name": "Mathlib.Algebra.Polynomial.PartialFractions",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) [inst : CommRing R] [IsDomain R] (K : Type u_2) [inst_2 : Field K] [inst_3 : Algebra (Polynomial R) K]\n  [IsFractionRing (Polynomial R) K] (f : Polynomial R) {ι : Type u_3} {g : ι → Polynomial R} {s : Finset ι},\n  (∀ i ∈ s, (g i).Monic) →\n    ((↑s).Pairwise fun i j => IsCoprime (g i) (g j)) →\n      ∃ q r, (∀ i ∈ s, (r i).degree < (g i).degree) ∧ ↑f / ∏ i ∈ s, ↑(g i) = ↑q + ∑ i ∈ s, ↑(r i) / ↑(g i)"
    }
  ]
